// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 funding, uint256 withdrawAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= funding);
        vm.assume(withdrawAmount <= funding);
        try c.sendMoney(address(c), funding, "") {} catch { return; }
        uint balBefore = address(c).balance;
        try c.withdraw(withdrawAmount) {} catch { return; }
        uint balAfter = address(c).balance;
        assertTrue(balAfter == balBefore - withdrawAmount);
    }

    function testFuzz_run(uint256 funding, uint256 withdrawAmount) public {
        _run(funding, withdrawAmount);
    }

    receive() external payable {}
}
